static int ath10k_tm_fetch_utf_firmware_api_1 ( struct ath10k * ar , struct ath10k_fw_file * fw_file ) { char filename [ 100 ] ; int ret ; snprintf ( filename , sizeof ( filename ) , "%s/%s" , ar -> hw_params . fw . dir , ATH10K_FW_UTF_FILE ) ; ret = request_firmware_direct ( & fw_file -> firmware , filename , ar -> dev ) ; ath10k_dbg ( ar , ATH10K_DBG_TESTMODE , "testmode fw request '%s': %d\n" , filename , ret ) ; fw_file -> wmi_op_version = ATH10K_FW_WMI_OP_VERSION_10_1 ; fw_file -> htt_op_version = ATH10K_FW_HTT_OP_VERSION_10_1 ; fw_file -> firmware_data = fw_file -> firmware -> data ; fw_file -> firmware_len = fw_file -> firmware -> size ; return 0 ; } 